-- Run after migrations 002, 003 and 004 on existing projects.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('vm-listing-covers','vm-listing-covers',true,5242880,array['image/png','image/jpeg','image/webp'])
on conflict(id) do update set public=true,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create or replace function public.vm_can_upload_cover(p_name text) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from vm.records r join vm.members m on m.id=r.owner where r.kind='listing' and r.owner=auth.uid() and (m.suspended_until is null or m.suspended_until<=now()) and not vm.is_sold(r.id) and split_part(p_name,'/',1)=auth.uid()::text and split_part(p_name,'/',2)=r.id::text and p_name ~ '^[0-9a-f-]+/[0-9a-f-]+/[0-9a-f-]+\.(png|jpg|webp)$');
$$;
revoke all on function public.vm_can_upload_cover(text) from public,anon;
grant execute on function public.vm_can_upload_cover(text) to authenticated;
drop policy if exists vm_cover_upload on storage.objects;
create policy vm_cover_upload on storage.objects for insert to authenticated with check(bucket_id='vm-listing-covers' and public.vm_can_upload_cover(name));
create or replace function public.vm_update_cover(p_listing uuid,p_image text) returns jsonb language plpgsql security definer set search_path='' as $$
declare m vm.members;r vm.records;path text;
begin
 m:=vm.ensure_member();if m.suspended_until>now() then raise exception 'Your account is temporarily suspended.' using errcode='42501';end if;
 select * into r from vm.records where id=p_listing and kind='listing' and owner=m.id for update;
 if r.id is null then raise exception 'Listing not found or not owned by you.' using errcode='42501';end if;
 if vm.is_sold(r.id) then raise exception 'A sold listing cannot be edited.';end if;
 if length(p_image)>1000 then raise exception 'Invalid cover image.';end if;
 if exists(select 1 from vm.catalog c where c.category='weapons' and c.id::text in (select jsonb_array_elements_text(coalesce(r.data->'inventory'->'weapons','[]'::jsonb))) and c.image=p_image) then
  null;
 else
  if p_image not like 'https://msmvmrzfaltsgdpaluyw.supabase.co/storage/v1/object/public/vm-listing-covers/%' then raise exception 'Choose an owned weapon or upload a cover picture.';end if;
  path:=substring(p_image from length('https://msmvmrzfaltsgdpaluyw.supabase.co/storage/v1/object/public/vm-listing-covers/')+1);
  if not public.vm_can_upload_cover(path) or split_part(path,'/',2)<>p_listing::text or not exists(select 1 from storage.objects where bucket_id='vm-listing-covers' and name=path) then raise exception 'Invalid uploaded cover.';end if;
 end if;
 update vm.records set data=jsonb_set(data,'{image}',to_jsonb(p_image)) where id=r.id;
 return jsonb_build_object('ok',true);
end;$$;
revoke all on function public.vm_update_cover(uuid,text) from public,anon;
grant execute on function public.vm_update_cover(uuid,text) to authenticated;
